package com.crazy4lamb.crmbi.controller;

import static com.crazy4lamb.crmbi.controller.AuthController.user;
import static com.crazy4lamb.crmbi.core.Api.ok;

import com.crazy4lamb.crmbi.core.ApiException;
import com.crazy4lamb.crmbi.core.Db;
import com.crazy4lamb.crmbi.core.UserPrincipal;
import com.crazy4lamb.crmbi.service.AclService;
import jakarta.servlet.http.HttpServletRequest;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/dashboard")
public class DashboardController {
  private final Db db; private final AclService acl;
  public DashboardController(Db db,AclService acl){this.db=db;this.acl=acl;}

  @GetMapping("/mine") public Map<String,Object> mine(@RequestParam(required=false)String dashboard,HttpServletRequest request){UserPrincipal u=user(request);return db.tx(u,ignored->{List<String>codes=acl.permissions(u.role()).getOrDefault("dashboard",List.of());if(codes.isEmpty())return ok(Map.of("dashboards",List.of(),"cards",List.of(),"charts",List.of()));Map<String,Object>p=Map.of("codes",codes);List<Map<String,Object>>dashes=db.many("select * from bi_dashboard where status='1' and code in (:codes) order by sort_no,id",p);if(dashes.isEmpty())return ok(Map.of("dashboards",List.of(),"cards",List.of(),"charts",List.of()));Map<String,Object>selected=dashes.stream().filter(x->dashboard!=null&&dashboard.equals(x.get("code"))).findFirst().orElse(dashes.getFirst());List<Map<String,Object>>items=db.many("select w.*,dw.col_span,dw.height from bi_dashboard_widget dw join bi_widget w on w.id=dw.widget_id where dw.dashboard_id=:id order by dw.sort_no",Map.of("id",selected.get("id")));List<Map<String,Object>>cards=new ArrayList<>(),charts=new ArrayList<>();for(Map<String,Object>w:items){String type=String.valueOf(w.get("widget_type"));if(!acl.can(u,"card".equals(type)?"card":"chart",String.valueOf(w.get("code"))))continue;Map<String,Object>x=new LinkedHashMap<>();x.put("code",w.get("code"));x.put("name",w.get("name"));x.put("span",w.get("col_span"));x.put("height",w.get("height"));if("card".equals(type)){x.put("icon",w.get("icon"));x.put("unit",w.get("unit"));x.put("fmt",w.get("fmt"));x.put("source",w.get("value_mode"));x.put("sumMode",w.get("sum_mode"));Object style=w.get("style");if(style instanceof Map<?,?>m)x.put("color",m.get("color"));cards.add(x);}else{x.put("chartType",w.get("chart_type"));x.put("scope",w.get("scope"));x.put("reportId",w.get("report_id"));charts.add(x);}}
      List<Map<String,Object>>dashList=dashes.stream().map(d->{Map<String,Object>x=new LinkedHashMap<>();x.put("code",d.get("code"));x.put("name",d.get("name"));x.put("description",d.get("description"));x.put("isDefault",d.get("is_default"));return x;}).toList();return ok(Map.of("dashboards",dashList,"dashboard",Map.of("code",selected.get("code"),"name",selected.get("name"),"description",String.valueOf(selected.getOrDefault("description",""))),"cards",cards,"charts",charts,"statDate",LocalDate.now().minusDays(1).toString()));});}

  @GetMapping("/widget/{code}") public Map<String,Object> widget(@PathVariable String code,HttpServletRequest request){UserPrincipal u=user(request);return db.tx(u,ignored->{Map<String,Object>w=db.one("select * from bi_widget where code=:code and status='1'",Map.of("code",code));if(w==null)throw ApiException.notFound("组件不存在");String type="card".equals(w.get("widget_type"))?"card":"chart";if(!acl.can(u,type,code))throw ApiException.forbidden("当前角色无权查看该组件");Map<String,Object>render=render(w);return ok(render);});}
  @GetMapping("/widgets") public Map<String,Object> widgets(@RequestParam String codes,HttpServletRequest request){UserPrincipal u=user(request);return db.tx(u,ignored->{List<String>list=java.util.Arrays.stream(codes.split(",")).map(String::trim).filter(v->!v.isEmpty()).limit(20).toList();if(list.isEmpty())return ok(List.of());List<Map<String,Object>>widgets=db.many("select * from bi_widget where code in (:codes)",Map.of("codes",list));List<Map<String,Object>>out=new ArrayList<>();for(Map<String,Object>w:widgets){String type="card".equals(w.get("widget_type"))?"card":"chart";if(acl.can(u,type,String.valueOf(w.get("code"))))out.add(render(w));}return ok(out);});}
  @GetMapping("/widget-library") public Map<String,Object> library(HttpServletRequest request){UserPrincipal u=user(request);return db.tx(u,ignored->{List<Map<String,Object>>rows=db.many("select * from bi_widget where status='1' order by widget_type,sort_no,id");return ok(rows.stream().filter(w->acl.can(u,"card".equals(w.get("widget_type"))?"card":"chart",String.valueOf(w.get("code")))).map(this::widgetMeta).toList());});}

  @GetMapping("/insights") public Map<String,Object> insights(HttpServletRequest request){UserPrincipal u=user(request);acl.require(u,"menu","dashboard","无权限查看驾驶舱");return db.tx(u,ignored->{String from=LocalDate.now().minusDays(29).toString(),to=LocalDate.now().toString();Map<String,Object>receivables=db.one("select coalesce(sum(unpaid_amount),0) amount,count(*) filter(where unpaid_amount>0)::int orders from crm_order_balance where status<>'refund'");Map<String,Object>opps=db.one("select count(*) filter(where expect_date<current_date)::int overdue,coalesce(sum(est_amount*win_rate/100.0),0) forecast from crm_opportunity where stage not in ('赢单','输单')");Map<String,Object>follow=db.one("select count(*) filter(where next_time<=now())::int due from crm_follow_up where next_time is not null");List<Map<String,Object>>raw=db.many("select * from bi_sales_trend(cast(:from as date),cast(:to as date))",Map.of("from",from,"to",to));List<Map<String,Object>>trend=raw.stream().map(r->{Map<String,Object>x=new LinkedHashMap<>();x.put("date",r.get("stat_date"));x.put("amount",r.get("sales_amount"));x.put("contracts",r.get("contract_count"));x.put("profit",r.get("profit"));x.put("runningAmount",r.get("running_amount"));x.put("previousAmount",r.get("previous_amount"));return x;}).toList();Map<String,Object>snapshot=db.one("select refreshed_at,source_version,refreshed_version,source_version>refreshed_version stale from bi_refresh_state where id=1");return ok(Map.of("enabled",true,"from",from,"to",to,"receivables",receivables,"opportunities",opps,"followups",follow,"snapshot",snapshot,"trend",trend));});}

  public Map<String,Object> render(Map<String,Object>w){String type=String.valueOf(w.get("widget_type"));Map<String,Object>result=new LinkedHashMap<>();result.put("code",w.get("code"));result.put("name",w.get("name"));result.put("widgetType",type);result.put("ok",true);if("card".equals(type))result.put("data",card(String.valueOf(w.get("code")),w));else{Map<String,Object>chart=chart(String.valueOf(w.get("chart_type")));result.put("chartType",w.get("chart_type"));result.put("data",Map.of("option",chart,"rows",List.of(),"columns",List.of(),"scope",String.valueOf(w.get("scope")),"totalRows",7));}return result;}
  private Map<String,Object> card(String code,Map<String,Object>w){String sql=code.contains("customer")?"select count(*) value from crm_customer":code.contains("lead")?"select count(*) value from crm_lead":code.contains("receiv")?"select coalesce(sum(unpaid_amount),0) value from crm_order_balance where status<>'refund'":"select coalesce(sum(amount),0) value from crm_contract where status in ('effective','closed')";Number value=(Number)db.one(sql).get("value");List<Map<String,Object>>days=db.many("select d::date as stat_date,coalesce(sum(c.amount),0) value from generate_series(current_date-13,current_date,'1 day') as d left join crm_contract c on c.sign_date=d::date and c.status in ('effective','closed') group by d order by d");List<Object>spark=days.stream().map(x->x.get("value")).toList();double raw=value.doubleValue();Map<String,Object>out=new LinkedHashMap<>();out.put("value",raw);out.put("rawValue",raw);out.put("display",String.format("%,.0f",raw));out.put("growth",0);out.put("growthText","0.0%");out.put("spark",spark);out.put("unit",w.get("unit"));return out;}
  private Map<String,Object> chart(String chartType){List<Map<String,Object>>rows=db.many("select coalesce(c.region,'未分类') label,coalesce(sum(t.amount),0) value from crm_contract t left join crm_customer c on c.id=t.customer_id where t.status in ('effective','closed') group by c.region order by value desc");List<String>labels=rows.stream().map(r->String.valueOf(r.get("label"))).toList();List<Object>values=rows.stream().map(r->r.get("value")).toList();Map<String,Object>option=new LinkedHashMap<>();option.put("tooltip",Map.of("trigger","axis"));String type=chartType==null?"bar":chartType;if(type.equals("pie")||type.equals("doughnut")||type.equals("funnel")){List<Map<String,Object>>data=rows.stream().map(r->Map.<String,Object>of("name",r.get("label"),"value",r.get("value"))).toList();option.put("series",List.of(Map.of("type",type.equals("doughnut")?"pie":type,"radius",type.equals("doughnut")?List.of("45%","72%"):"68%","data",data)));}else if(type.equals("gauge")){option.put("series",List.of(Map.of("type","gauge","data",List.of(Map.of("value",72,"name","目标达成率")))));}else if(type.equals("radar")){option.put("radar",Map.of("indicator",labels.stream().map(x->Map.of("name",x,"max",10000000)).toList()));option.put("series",List.of(Map.of("type","radar","data",List.of(Map.of("value",values,"name","签约额")))));}else if(type.equals("scatter")){option.put("xAxis",Map.of());option.put("yAxis",Map.of());option.put("series",List.of(Map.of("type","scatter","data",java.util.stream.IntStream.range(0,values.size()).mapToObj(i->List.of(i,values.get(i))).toList())));}else if(type.equals("heatmap")){option.put("xAxis",Map.of("type","category","data",labels));option.put("yAxis",Map.of("type","category","data",List.of("签约")));option.put("visualMap",Map.of("min",0,"max",10000000));option.put("series",List.of(Map.of("type","heatmap","data",java.util.stream.IntStream.range(0,values.size()).mapToObj(i->List.of(i,0,values.get(i))).toList())));}else{boolean horizontal=type.equals("bar_h");option.put(horizontal?"yAxis":"xAxis",Map.of("type","category","data",labels));option.put(horizontal?"xAxis":"yAxis",Map.of("type","value"));Map<String,Object>series=new LinkedHashMap<>();series.put("type",type.startsWith("line")||type.equals("area")?"line":"bar");if(type.equals("area"))series.put("areaStyle",Map.of());series.put("data",values);option.put("series",List.of(series));}return option;}
  private Map<String,Object>widgetMeta(Map<String,Object>w){Map<String,Object>x=new LinkedHashMap<>();for(String k:List.of("id","code","name"))x.put(k,w.get(k));x.put("widgetType",w.get("widget_type"));x.put("chartType",w.get("chart_type"));x.put("reportId",w.get("report_id"));x.put("metricId",w.get("metric_id"));x.put("valueMode",w.get("value_mode"));x.put("scope",w.get("scope"));x.put("sumMode",w.get("sum_mode"));x.put("unit",w.get("unit"));x.put("dims",w.get("dimension_keys"));x.put("series",w.get("series"));x.put("filters",w.get("filters"));x.put("style",w.get("style"));x.put("limit",w.get("limit_rows"));x.put("sortStrategy",w.get("sort_strategy"));x.put("compare",w.get("compare"));x.put("icon",w.get("icon"));return x;}
}
